ALTER TABLE public.ride_requests ADD COLUMN IF NOT EXISTS saved_patient_id uuid REFERENCES public.saved_patients(id), ADD COLUMN IF NOT EXISTS coordination_contact_id uuid REFERENCES public.provider_contacts(id);
CREATE OR REPLACE FUNCTION public.authorized_trip_record(_actor uuid,_ws uuid,_kind text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=_actor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND (NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.record_permissions->>_kind IN ('read','manage')) OR EXISTS(SELECT 1 FROM public.workspace_record_shares s WHERE s.workspace_id=_ws AND s.user_id=_actor AND s.record_kind=_kind AND s.record_id=_id))) $$;
REVOKE ALL ON FUNCTION public.authorized_trip_record(uuid,uuid,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.authorized_trip_record(uuid,uuid,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.trip_contact_attachment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.saved_patients; c public.provider_contacts; BEGIN
IF TG_OP='UPDATE' THEN IF NEW.saved_patient_id IS DISTINCT FROM OLD.saved_patient_id OR NEW.coordination_contact_id IS DISTINCT FROM OLD.coordination_contact_id OR NEW.payer_id IS DISTINCT FROM OLD.payer_id THEN RAISE EXCEPTION 'Trip billing/contact references are immutable'; END IF; RETURN NEW; END IF;
IF NEW.payer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.payers x WHERE x.id=NEW.payer_id AND x.active AND x.workspace_id=NEW.workspace_id AND public.authorized_trip_record(NEW.actor_user_id,NEW.workspace_id,'payers',x.id)) THEN RAISE EXCEPTION 'Payer not available'; END IF;
IF NEW.coordination_contact_id IS NOT NULL THEN SELECT * INTO c FROM public.provider_contacts WHERE id=NEW.coordination_contact_id AND active AND coordination_allowed AND workspace_id=NEW.workspace_id; IF c.id IS NULL OR NOT public.authorized_trip_record(NEW.actor_user_id,NEW.workspace_id,'contacts',c.id) THEN RAISE EXCEPTION 'Contact not available'; END IF; END IF;
IF NEW.saved_patient_id IS NOT NULL THEN
 SELECT * INTO p FROM public.saved_patients WHERE id=NEW.saved_patient_id AND active AND kind='patient';
 IF p.id IS NULL OR NOT (p.owner_id=NEW.actor_user_id OR p.workspace_id=NEW.workspace_id AND EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=p.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL) OR p.workspace_id IS NOT NULL AND NEW.patient_workspace_id IS NOT NULL AND p.linked_patient_workspace_id=NEW.patient_workspace_id AND EXISTS(SELECT 1 FROM public.workspaces w JOIN public.account_business_connections b ON b.active AND b.workspace_a=least(w.id,NEW.workspace_id) AND b.workspace_b=greatest(w.id,NEW.workspace_id) WHERE w.id=p.workspace_id AND w.account_type IN ('facility','hospital')) AND EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL)) THEN RAISE EXCEPTION 'Patient not available'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER trip_contact_attachment_guard BEFORE INSERT OR UPDATE ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.trip_contact_attachment_guard();
CREATE OR REPLACE FUNCTION public.linked_patient_trip_defaults(_source uuid,_patient uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE owner_uid uuid; s public.saved_patients; p public.user_profiles; BEGIN
IF NOT public.can_manage_account_connections(_source) OR NOT EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND c.workspace_a=least(_source,_patient) AND c.workspace_b=greatest(_source,_patient)) THEN RETURN NULL; END IF;
SELECT m.user_id INTO owner_uid FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles u ON u.user_id=m.user_id JOIN auth.users a ON a.id=m.user_id WHERE w.id=_patient AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.status='active' AND NOT u.is_test_account AND u.deleted_at IS NULL AND a.email_confirmed_at IS NOT NULL;
IF owner_uid IS NULL THEN RETURN NULL; END IF;
SELECT * INTO p FROM public.user_profiles WHERE user_id=owner_uid;
SELECT * INTO s FROM public.saved_patients WHERE owner_id=owner_uid AND active AND kind='patient' ORDER BY created_at LIMIT 1;
IF s.id IS NULL THEN RETURN NULL; END IF;
RETURN jsonb_build_object('patientFirstName',s.first_name,'patientLastName',s.last_name,'patientPhone',coalesce(s.phone,p.phone),'patientEmail',s.email,'transportType',CASE WHEN s.mobility='stretcher' THEN 'gurney' WHEN s.mobility='wheelchair' THEN 'wheelchair' ELSE 'ambulatory' END,'patientWorkspaceId',_patient);
END $$;
REVOKE ALL ON FUNCTION public.linked_patient_trip_defaults(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.linked_patient_trip_defaults(uuid,uuid) TO authenticated;
COMMENT ON COLUMN public.ride_requests.saved_patient_id IS 'Explicit authorized patient selection; no diagnosis, note, document or payment-default copying.';
COMMENT ON COLUMN public.ride_requests.coordination_contact_id IS 'Immutable authorized trip coordination reference; never grants record access.';